head.script:
scwin.gLdMktTp = js_market;
scwin.gParamObj;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        scwin.hideDebugCtrls();
        $c.libRoundPanel.PanelToGroupBox(panel_1);
        scwin.resizeToWin();
        scwin.getParam();
        scwin.init();
        await scwin.listDisclosure();
        // MoveCenterOfParent();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30003.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function() {
    if (js_market === "9") {
        rdo_MKT_ID.setValue(scwin.gLdMktTp);
        rdo_MKT_ID.setDisabled(false);
    } else {
        rdo_MKT_ID.setValue(scwin.gLdMktTp);
        rdo_MKT_ID.setDisabled(true);
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_Discls_OnDblClick
 * @description grd_Discls 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Discls_OnDblClick = async function(row, colid) {
    try {
        await scwin.setAcpt_No(grd_Discls, row, colid);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30003.grd_Discls_OnDblClick" });
    }
};

/**
 * @method
 * @name dts_Discls_OnLoadCompleted
 * @description dts_Discls 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Discls_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
        // setObjectValue(txb_TotalCnt, "총 " + FormatNumberEx(rowcount) + " 건");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30003.dts_Discls_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name rdo_MKT_ID_onselchange
 * @description rdo_MKT_ID onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.rdo_MKT_ID_onselchange = function() {
    // fn_listDisclosure();

};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.listDisclosure();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30003.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name txb_FORM_KOR_NM_onkeydown
 * @description txb_FORM_KOR_NM 키 입력 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txb_FORM_KOR_NM_onkeydown = async function() {
    try {
        if (window.event.keyCode === "13") {
            await scwin.listDisclosure();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30003.txb_FORM_KOR_NM_onkeydown" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listDisclosure
 * @description list Disclosure 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listDisclosure = async function() {
    // var MARKET_FLAG = getObjectValue(rdo_Tab1_Market_Flag);
    url += "&MKT_ID=" + rdo_MKT_ID.getValue();
    url += "&FORM_NM=" + txb_FORM_KOR_NM.getValue();
    url += "&SCREN_ID=" + 'ULDSTF30003.xml';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_Discls",
        action : "/DisclosureSchedule.do",
        ref : "",
        target : "dts_Discls=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name resizeToWin
 * @description resize To Win 처리
 * @returns {void}
 * @hidden N
 */
scwin.resizeToWin = function() {
    frame.Width = 480;
    frame.Height = 530;
};

/**
 * @method
 * @name getParam
 * @description opener로 부터 param을 받는다.
 * @returns {void}
 * @hidden N
 */
scwin.getParam = function() {
    // opener로 부터 param을 받는다.
    let parentWin = $c.frame.path("../");
    const paramObj = parentWin.scwin.gParamObj;
    const ISURCD = paramObj.param0;
    txb_ISUR_CD.setValue(ISURCD);
};

/**
 * @method
 * @name setParam
 * @description child에 param을 넘긴다.
 * @returns {void}
 * @hidden N
 */
scwin.setParam = function() {
    // child에 param을 넘긴다.
    const argv = scwin.setParam.arguments;
    const argc = scwin.setParam.arguments.length;
    scwin.gParamObj = new Array(argc); // 초기화
    for (let i = 0; i < argc; i++) // actual arguments

    {
        eval("gParamObj.param" + i + " = argv[" + i + "]");
    }
    return true;
};

/**
 * @method
 * @name setAcpt_No
 * @description set Acpt No 처리
 * @param {String} GridID GridID
 * @param {Number} row 행 인덱스
 * @param {String} ColID ColID
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setAcpt_No = async function(GridID, row, ColID) {
    const objDataID = document.all(GridID.DataID); // 가져오는 방식이 좀 특이하다..

    const vFORM_CD = objDataID.getCellData(row, "FORM_CD");
    const vFORM_KOR_NM = objDataID.getCellData(row, "FORM_KOR_NM");
    let parentWin = $c.frame.path("../");
    if (parentWin.txb_Tab1_RptCd === null) {
        // 유가.
        parentWin.txb_FORM_CD.setValue(vFORM_CD);
        parentWin.txb_FORM_KOR_NM.setValue(vFORM_KOR_NM);
    } else {
        parentWin.txb_Tab1_RptCd.setValue(vFORM_CD);
        parentWin.txb_Tab1_RptNm.setValue(vFORM_KOR_NM);
    }
    await $c.win.closePopup();
};

/**
 * @method
 * @name hideDebugCtrls
 * @description 키값으로 사용하지만 화면상에 표시될 필요가 없는 것들
 * @returns {void}
 * @hidden N
 */
scwin.hideDebugCtrls = function() {
    // 키값으로 사용하지만 화면상에 표시될 필요가 없는 것들
    panel_debug.hide();
};
